import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { FiEdit3 } from "react-icons/fi";

import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import FormField from "../../components/FormField";

import { registrationApi } from "../../api/registrationApi";
import { studentApi } from "../../api/studentApi";
import { courseApi } from "../../api/courseApi";

import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";

import {
  validateFields,
  isRequired
} from "../../utils/validators";

import { fullName } from "../../utils/formatters";

const SEMESTER_OPTIONS = [
  {
    value: "Semester I",
    label: "Semester I"
  },
  {
    value: "Semester II",
    label: "Semester II"
  },
  {
    value: "Summer",
    label: "Summer"
  }
];

const initialValues = {
  student_id: "",
  course_id: "",
  semester: "",
  academic_year: ""
};

export default function RegistrationStudent() {
  const navigate = useNavigate();
  const toast = useToast();

  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState({});

  const [students, setStudents] = useState([]);
  const [courses, setCourses] = useState([]);

  const [loadingStudents, setLoadingStudents] = useState(true);
  const [loadingCourses, setLoadingCourses] = useState(true);

  const [isSubmitting, setIsSubmitting] = useState(false);

  // =========================================================
  // LOAD STUDENTS
  // =========================================================

  useEffect(() => {
    let mounted = true;

    async function loadStudents() {
      setLoadingStudents(true);

      try {
        const response = await studentApi.getAll();

        if (!mounted) return;

        const responseData = response?.data;

        let list = [];

        if (Array.isArray(responseData)) {
          list = responseData;
        } else if (Array.isArray(responseData?.data)) {
          list = responseData.data;
        } else if (Array.isArray(responseData?.students)) {
          list = responseData.students;
        } else if (Array.isArray(responseData?.items)) {
          list = responseData.items;
        }

        setStudents(list);
      } catch (err) {
        if (!mounted) return;

        setStudents([]);

        toast.error(
          extractErrorMessage(
            err,
            "Unable to load students."
          )
        );
      } finally {
        if (mounted) {
          setLoadingStudents(false);
        }
      }
    }

    loadStudents();

    return () => {
      mounted = false;
    };
  }, [toast]);

  // =========================================================
  // LOAD COURSES
  // =========================================================

  useEffect(() => {
    let mounted = true;

    async function loadCourses() {
      setLoadingCourses(true);

      try {
        const response = await courseApi.getAll();

        if (!mounted) return;

        const responseData = response?.data;

        let list = [];

        if (Array.isArray(responseData)) {
          list = responseData;
        } else if (Array.isArray(responseData?.data)) {
          list = responseData.data;
        } else if (Array.isArray(responseData?.courses)) {
          list = responseData.courses;
        } else if (Array.isArray(responseData?.items)) {
          list = responseData.items;
        }

        setCourses(list);
      } catch (err) {
        if (!mounted) return;

        setCourses([]);

        toast.error(
          extractErrorMessage(
            err,
            "Unable to load courses."
          )
        );
      } finally {
        if (mounted) {
          setLoadingCourses(false);
        }
      }
    }

    loadCourses();

    return () => {
      mounted = false;
    };
  }, [toast]);

  // =========================================================
  // STUDENT OPTIONS
  // =========================================================

  const studentOptions = students
    .map((student) => {
      const id =
        student.student_id ??
        student.id;

      if (!id) return null;

      return {
        value: String(id),
        label: `${fullName(student)}${
          student.registration_number
            ? ` — ${student.registration_number}`
            : ""
        }`
      };
    })
    .filter(Boolean);

  // =========================================================
  // COURSE OPTIONS
  // =========================================================

  const courseOptions = courses
    .map((course) => {
      const id =
        course.course_id ??
        course.id;

      if (!id) return null;

      const code =
        course.course_code ??
        course.code ??
        "";

      const name =
        course.course_name ??
        course.name ??
        "";

      return {
        value: String(id),
        label: `${code}${code && name ? " — " : ""}${name}`
      };
    })
    .filter(Boolean);

  // =========================================================
  // HANDLE INPUT CHANGE
  // =========================================================

  function handleChange(e) {
    const { name, value } = e.target;

    setValues((previous) => ({
      ...previous,
      [name]: value
    }));

    setErrors((previous) => ({
      ...previous,
      [name]: ""
    }));
  }

  // =========================================================
  // HANDLE SUBMIT
  // =========================================================

  async function handleSubmit(e) {
    e.preventDefault();

    const fieldErrors = validateFields(values, {
      student_id: [isRequired],
      course_id: [isRequired],
      semester: [isRequired],
      academic_year: [isRequired]
    });

    if (Object.keys(fieldErrors).length > 0) {
      setErrors(fieldErrors);

      toast.error(
        "Please complete all required fields."
      );

      return;
    }

    setIsSubmitting(true);

    try {
      await registrationApi.create({
        student_id: Number(values.student_id),
        course_id: Number(values.course_id),
        semester: values.semester,
        academic_year: values.academic_year
      });

      toast.success(
        "Student registered for the course successfully."
      );

      navigate(
        `/registrations/student/${values.student_id}`
      );
    } catch (err) {
      toast.error(
        extractErrorMessage(
          err,
          "Unable to register this course."
        )
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  // =========================================================
  // PAGE
  // =========================================================

  return (
    <DashboardLayout>

      <div className="max-w-lg mx-auto">

        {/* PAGE HEADER */}

        <div className="flex items-center gap-2 mb-6">

          <div className="h-9 w-9 rounded-lg bg-navy-100 text-navy-700 flex items-center justify-center">

            <FiEdit3 size={16} />

          </div>

          <h1 className="font-display text-xl text-navy-800">
            Register Student
          </h1>

        </div>

        {/* FORM CARD */}

        <Card className="p-6">

          <form
            onSubmit={handleSubmit}
            className="space-y-4"
            noValidate
          >

            {/* STUDENT */}

            <FormField
              as="select"
              label="Select Student"
              name="student_id"
              value={values.student_id}
              onChange={handleChange}
              error={errors.student_id}
              required
              options={studentOptions}
              placeholder={
                loadingStudents
                  ? "Loading students..."
                  : studentOptions.length === 0
                  ? "No students available"
                  : "Select a student"
              }
            />

            {/* COURSE */}

            <FormField
              as="select"
              label="Select Course"
              name="course_id"
              value={values.course_id}
              onChange={handleChange}
              error={errors.course_id}
              required
              options={courseOptions}
              placeholder={
                loadingCourses
                  ? "Loading courses..."
                  : courseOptions.length === 0
                  ? "No courses available"
                  : "Select a course"
              }
            />

            {/* SEMESTER + ACADEMIC YEAR */}

            <div className="grid sm:grid-cols-2 gap-4">

              <FormField
                as="select"
                label="Semester"
                name="semester"
                value={values.semester}
                onChange={handleChange}
                error={errors.semester}
                required
                options={SEMESTER_OPTIONS}
                placeholder="Select semester"
              />

              <FormField
                label="Academic Year"
                name="academic_year"
                value={values.academic_year}
                onChange={handleChange}
                error={errors.academic_year}
                required
                placeholder="e.g. 2025/2026"
              />

            </div>

            {/* BUTTONS */}

            <div className="flex gap-3 pt-2">

              <button
                type="button"
                onClick={() => navigate("/registrations")}
                disabled={isSubmitting}
                className="flex-1 py-2.5 rounded-lg text-sm border border-line text-ink hover:bg-paper transition disabled:opacity-60"
              >
                Cancel
              </button>

              <button
                type="submit"
                disabled={
                  isSubmitting ||
                  loadingStudents ||
                  loadingCourses
                }
                className="flex-1 py-2.5 rounded-lg text-sm bg-navy-700 text-white hover:bg-navy-800 transition disabled:opacity-60"
              >
                {isSubmitting
                  ? "Registering..."
                  : "Register Course"}
              </button>

            </div>

          </form>

        </Card>

      </div>

    </DashboardLayout>
  );
}
